export function readJsonScript(id, fallback) {
    var node = document.getElementById(id);
    if (!node)
        return fallback;
    var content = node.textContent || '';
    if (!content.trim())
        return fallback;
    try {
        return JSON.parse(content);
    }
    catch (err) {
        console.error("Failed to parse JSON script #".concat(id), err);
        return fallback;
    }
}
